const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const smoothstep = (a, b, x) => {
    const u = clamp((x - a) / Math.max(1e-6, b - a), 0, 1);
    return u * u * (3 - 2 * u);
};
const seeded = (seed) => {
    const x = Math.sin(seed * 999.17) * 43758.5453;
    return x - Math.floor(x);
};

