function createSoil(world,seedOffset=0,detached=false){
 const soilSeed=value=>seeded(value+seedOffset);
 const nodes=[],edges=[],bridges=[],groups=[[],[],[]],centers=[.27,.74,.51];
 const addNode=(x,y,group)=>{const id=nodes.length;nodes.push({id,x,y,group,edges:[],light:0,memory:0});groups[group].push(id);return id;};
 const addEdge=(from,to,bridge=-1)=>{
  const a=nodes[from],b=nodes[to],id=edges.length;
  const e={id,from,to,bridge,length:Math.hypot(b.x-a.x,(b.y-a.y)*.75),growth:bridge<0?.035:0,light:0,memory:0,conductance:0,blocked:false,phase:soilSeed(id+453)*6.283};
  edges.push(e);a.edges.push(id);b.edges.push(id);return e;
 };
 // Each root has a connected local patch, with occasional loops. Topology is
 // built once; all traversal afterwards uses bounded adjacency lists.
 for(let g=0;g<3;g++){
  addNode(centers[g],.775,g);
  for(let i=0;i<20;i++){
   const seed=83+g*109+i*19;
   const x=clamp(centers[g]+(soilSeed(seed)-.5)*.28,.025,.975),y=.795+soilSeed(seed+4)*.18;
   let closest=groups[g][0],distance=Infinity;
   for(const id of groups[g]){const n=nodes[id],d=Math.hypot(x-n.x,(y-n.y)*.75);if(d<distance){closest=id;distance=d;}}
   addEdge(closest,addNode(x,y,g));
  }
  for(let i=4;i<groups[g].length;i+=4){
   const a=nodes[groups[g][i]];let target=-1,best=.10;
   for(const id of groups[g]){
    const b=nodes[id],dist=Math.hypot(a.x-b.x,(a.y-b.y)*.75);
    if(id!==a.id&&b.edges.length<4&&dist<best&&!a.edges.some(e=>edges[e].from===id||edges[e].to===id)){target=id;best=dist;}
   }
   if(target>=0)addEdge(a.id,target);
  }
 }
 for(const [a,b,key]of [[0,1,'hl'],[0,2,'hm'],[1,2,'lm']]){
  let pair=[groups[a][0],groups[b][0]],best=Infinity;
  for(const i of groups[a])for(const j of groups[b]){
   const p=nodes[i],q=nodes[j],d=Math.hypot(p.x-q.x,p.y-q.y);
   if(d<best){best=d;pair=[i,j];}
  }
  const edge=addEdge(pair[0],pair[1],bridges.length);edge.key=key;bridges.push(edge);
 }
 for(const edge of edges)edge.samples=Array.from({length:25},(_,i)=>soilEdgePoint({nodes},edge,i/24,1,1));
 const soil={nodes,edges,bridges,groups,age:0,packets:[],serial:0,food:[0,0,0],touch:{x:.5,y:.5,force:0,down:false},
  contacts:[0,0,0],activity:0,pressure:0,refusing:false,hadInput:false,quietFor:0,quietSent:false,lastBeat:0,arrivals:0,storyArrivals:0,
  story:{queue:[],current:null,incoming:null,changedAt:0,transitionAt:0,last:{},indices:{},shown:[],age:0},voiceCharge:[0,0,0]};
 if(!detached){H.ecology=soil;installSoilText(soil);installSoilPointer(soil);}return soil;
}
function queueSoil(soil,key,priority=0){
 if(soil!==H.ecology)return;
 if(H.actII?.enabled){queueActII(key,priority);return;}
 const story=soil.story;if(!SOIL_TEXT[key]||story.queue.some(q=>q.key===key)||story.incoming?.key===key)return;
 if(soil.age-(story.last[key]??-100)<22)return;
 // Seven waiting cues at most. Preserve waiting voices; urgent refusal may
 // replace a newly queued lower-priority cue, never an already-reading line.
 if(story.queue.length>=7){
  if(priority<4)return;
  let replace=-1;
  for(let i=story.queue.length-1;i>=0;i--)if(story.queue[i].priority<priority&&soil.age-story.queue[i].queuedAt<20){replace=i;break;}
  if(replace<0)return;const removed=story.queue.splice(replace,1)[0];
  if(removed.actSerial===H.drama.serial){H.drama.queued=false;H.drama.nextCue=removed.cueIndex;}
 }
 story.queue.push({key,priority,queuedAt:soil.age});
}
function takeSoilCue(soil){
 // Age is only reading-queue fairness, not a source of new narrative events.
 // Repeated bridge traffic must not silence the quieter language voices.
 const score=item=>item.priority+(soil.age-item.queuedAt)/6;
 const queue=soil.story.queue;
 queue.sort((a,b)=>score(b)-score(a));
 const urgent=queue.findIndex(item=>item.priority>=4);
 if(urgent>=0)return queue.splice(urgent,1)[0];
 const act=queue.findIndex(item=>item.actSerial!==undefined);
 if(act>=0&&soil.story.current?.actSerial===undefined)return queue.splice(act,1)[0];
 const encounter=queue.findIndex(item=>item.actSerial===undefined);
 if(encounter>=0&&soil.story.current?.actSerial!==undefined)return queue.splice(encounter,1)[0];
 return queue.shift();
}

function soilEdgePoint(soil,edge,u,w,h){
 if(edge.samples){const t=clamp(u)*24,index=Math.min(23,Math.floor(t)),v=t-index;return [lerp(edge.samples[index][0],edge.samples[index+1][0],v)*w,lerp(edge.samples[index][1],edge.samples[index+1][1],v)*h];}
 const a=soil.nodes[edge.from],b=soil.nodes[edge.to];
 const arch=Math.sin(u*Math.PI),bend=Math.sin(u*5+edge.phase)*arch;
 return [lerp(a.x,b.x,u)*w+bend*w*.007,lerp(a.y,b.y,u)*h-arch*h*(edge.bridge>=0?.018:.009)+bend*h*.009];
}
function installSoilPointer(){H.disposeSoil=()=>H.soilReading?.remove();}
const SOIL_SERIF='"Cormorant Garamond", Georgia, serif';
const SOIL_URDU='"Noto Nastaliq Urdu", "Urdu Typesetting", "Nirmala UI", "Noto Naskh Arabic", Amiri, serif';
function installSoilText(soil){
 document.getElementById('hagen-soil-reading')?.remove();document.getElementById('hagen-soil-text')?.remove();
 const reading=document.createElement('div');reading.id='hagen-soil-reading';
 reading.setAttribute('role','status');reading.setAttribute('aria-live','polite');reading.setAttribute('aria-atomic','true');reading.setAttribute('aria-hidden','true');
 const style=document.createElement('style');style.textContent=`
  #hagen-soil-reading{pointer-events:none}
  #hagen-soil-text{position:fixed;left:50%;bottom:13vh;transform:translateX(-50%);width:min(82vw,800px);margin:0;padding:0;z-index:2147483000;color:#eee5d1;font-family:${SOIL_SERIF};font-size:clamp(18px,2.15vw,28px);font-weight:400;line-height:1.38;text-align:center;text-shadow:0 2px 12px #000,0 0 5px #000;opacity:0}
  #hagen-soil-voices{position:fixed;left:50%;top:37vh;transform:translate(-50%,-50%);width:min(84vw,850px);z-index:2147483001;text-align:center;color:#eee5d1;text-shadow:0 2px 18px #000,0 0 8px #000;opacity:0}
  #hagen-soil-whisper{margin:0;padding:.25em 0;font-family:${SOIL_SERIF};font-size:clamp(25px,3.4vw,44px);line-height:1.4;font-style:italic;font-weight:400;unicode-bidi:isolate;overflow-wrap:break-word}
  #hagen-soil-whisper[dir=rtl]{font-family:${SOIL_URDU};font-size:clamp(24px,3vw,40px);font-style:normal;line-height:2.25;padding:.45em 0}
  #hagen-soil-gloss{margin:12px 0 0;font:400 clamp(15px,1.6vw,21px)/1.45 ${SOIL_SERIF};color:#c6cbc6;unicode-bidi:isolate}
  @media(max-height:550px){#hagen-soil-voices{top:30vh;width:85vw}#hagen-soil-whisper{font-size:clamp(19px,3.2vw,28px)}#hagen-soil-whisper[dir=rtl]{font-size:22px;line-height:1.9}#hagen-soil-gloss{font-size:14px;margin-top:4px}#hagen-soil-text{font-size:17px;bottom:15vh}}
 `;reading.appendChild(style);
 const voices=document.createElement('div');voices.id='hagen-soil-voices';voices.dataset.hagenLayer='13_NARRATIVE_VOICES';
 const whisper=document.createElement('p');whisper.id='hagen-soil-whisper';voices.appendChild(whisper);
 const gloss=document.createElement('p');gloss.id='hagen-soil-gloss';voices.appendChild(gloss);reading.appendChild(voices);
 const line=document.createElement('p');line.id='hagen-soil-text';line.dataset.hagenLayer='13_NARRATIVE_TEXT';reading.appendChild(line);
 document.body.appendChild(reading);H.soilReading=reading;H.soilText=line;H.soilVoices=voices;H.soilWhisper=whisper;H.soilGloss=gloss;
 H.textSettings=H.textSettings||{lang:'en',visible:true,culture:true,translations:false,romanUrdu:false};
 renderSoilText();
}
// All text surfaces use the same culture setting. Localized narrative whispers remain.
function soilVoice(line){
 const voice=line?.[4];return voice&&(H.textSettings.culture||voice.localized)?voice:null;
}
function soilLineAllowed(line){return !line?.[5]||!line[4]||!!soilVoice(line);}
function completeSoilActCue(item){
 if(item?.actSerial===H.drama.serial){H.drama.delivered++;H.drama.queued=false;}
}
function clearSoilSediment(){
 H.garden?.refreshText?.();
 const surface=H.livingWorld?.surfaces['14_LEXIA_SEDIMENT'];
 if(surface){surface.ctx.save();surface.ctx.setTransform(1,0,0,1,0,0);surface.ctx.clearRect(0,0,surface.canvas.width,surface.canvas.height);surface.ctx.restore();}
}
function setCultureEnabled(enabled){
 const changed=H.textSettings.culture!==!!enabled;H.textSettings.culture=!!enabled;
 const soil=H.ecology,story=soil?.story;
 if(changed&&story){
  // Count suppressed standalone act cues as passed, so Culture off cannot stall an act.
  story.queue=story.queue.filter(item=>{
   if(!item.line||soilLineAllowed(item.line))return true;
   completeSoilActCue(item);return false;
  });
  if(story.incoming?.line&&!soilLineAllowed(story.incoming.line)){
   completeSoilActCue(story.incoming);story.incoming=null;story.transitionAt=0;
  }
  if(story.current&&!soilLineAllowed(story.current.line)){
   story.current=null;
   // Commit an already selected next cue before taking a newer queued cue.
   if(story.incoming)setSoilLine(soil,story.incoming);
  }
  updateSoilStory(soil,0);
 }
 clearSoilSediment();renderSoilText();H.refreshTextControls?.();
}
function renderSoilText(){
 const current=H.ecology?.story.current;if(!H.soilText)return;
 const settings=H.textSettings,lang=settings.lang==='no'?'nb':'en',line=current?.line,voice=soilVoice(line);
 H.soilReading.style.display=settings.visible?'':'none';H.soilReading.setAttribute('aria-hidden',String(!settings.visible||!current));
 H.soilText.textContent=line&&!line[5]?line[lang==='en'?1:0]:'';H.soilText.lang=lang;H.soilText.dir='ltr';
 H.soilVoices.style.display=voice?'':'none';H.soilVoices.setAttribute('aria-hidden',String(!settings.visible||!voice));
 const roman=voice?.lang==='ur'&&settings.romanUrdu;
 H.soilWhisper.textContent=voice?(voice.localized?voice[settings.lang]:roman?voice.roman:voice.text):'';
 H.soilWhisper.lang=voice?(voice.localized?lang:roman?'ur-Latn':voice.lang):lang;
 H.soilWhisper.dir=voice?.lang==='ur'&&!roman?'rtl':'ltr';
 const translation=voice?.[settings.lang];
 H.soilGloss.textContent=voice&&!voice.localized&&settings.translations&&translation!==voice.text?translation:'';
 H.soilGloss.lang=lang;H.soilGloss.dir='ltr';H.soilGloss.style.display=H.soilGloss.textContent?'':'none';
}
function soilReadingTime(line){
 const voice=soilVoice(line),voiceLength=voice?(voice.roman||voice.text).length:0;
 const translated=H.textSettings.translations&&voice?Math.max(voice.no.length,voice.en.length):0;
 return Math.max(8,((line[5]?0:Math.max(line[0].length,line[1].length))+voiceLength+translated)/14+3);
}

function setSoilLine(soil,item){
 const story=soil.story,bank=item.line?[item.line]:SOIL_TEXT[item.key],index=item.line?0:(story.indices[item.key]||0)%bank.length;
 if(!soilLineAllowed(bank[index])){
  completeSoilActCue(item);story.incoming=null;story.transitionAt=0;return;
 }
 if(story.current){
  const slot=(story.sedimentSerial||0)%3;story.sedimentSerial=(story.sedimentSerial||0)+1;
  story.shown=story.shown.filter(s=>s.slot!==slot);
  story.shown.push({line:story.current.line,slot,x:[.26,.5,.74][slot],y:slot===1?.97:.934,age:0,gardenX:H.garden?.player.x,gardenZ:H.garden?.player.z});
  if(story.shown.length>3)story.shown.shift();
 }
 story.current={key:item.key,line:bank[index],actSerial:item.actSerial};
 completeSoilActCue(item);story.indices[item.key]=(story.indices[item.key]||0)+1;
 story.last[item.key]=soil.age;story.changedAt=soil.age;story.incoming=null;story.transitionAt=0;
 renderSoilText();
}
function updateSoilStory(soil,dt){
 const story=soil.story;for(const s of story.shown)s.age+=dt;
 while(!story.current&&story.queue.length)setSoilLine(soil,takeSoilCue(soil));
 if(story.current&&!story.incoming&&story.queue.length){
  const readingTime=soilReadingTime(story.current.line);
  if(soil.age-story.changedAt>readingTime){story.incoming=takeSoilCue(soil);story.transitionAt=soil.age;}
 }
 if(story.incoming&&soil.age-story.transitionAt>.8)setSoilLine(soil,story.incoming);
 if(H.soilText){
  const alpha=story.incoming?1-clamp((soil.age-story.transitionAt)/.8):clamp((soil.age-story.changedAt)/1.1);
  H.soilText.style.opacity=String(H.textSettings.visible&&story.current?alpha:0);
  H.soilVoices.style.opacity=H.soilText.style.opacity;
 }
}
function updateSoil(world,a,c,dt){
 const soil=world.ecology||(world.ecology=createSoil(world));soil.age+=dt;
 const level=clamp(a.fastLevel||0),motion=clamp(c.motion||0),presence=clamp(c.occupancy||0);
 if(!soil.touch.down)soil.touch.force*=Math.exp(-dt*1.5);
 const touched=soil.touch.force,spatial=Math.max(motion*.8+presence*.22,touched,world.garden?.nearby||0);
 const x=touched>motion?soil.touch.x:(c.x??.5),energies=[clamp(a.low||0),clamp(a.high||0),clamp(a.mid||0)];
 soil.activity=lerp(soil.activity,level,1-Math.exp(-dt*4));
 if(level>.035){
  if(!soil.hadInput){soil.hadInput=true;queueSoil(soil,'wake',3);}else if(soil.quietSent){soil.quietSent=false;queueSoil(soil,'return',2);}
  soil.quietFor=0;
 }else{soil.quietFor+=dt;if(soil.hadInput&&soil.quietFor>8&&!soil.quietSent){soil.quietSent=true;queueSoil(soil,'quiet',3);}}
 // Pressure limits transport, never audio sensing or the figures' response.
 soil.pressure=clamp(soil.pressure+dt*(level>.9?.065:-.09));
 if(soil.pressure>.8&&!soil.refusing){soil.refusing=true;queueSoil(soil,'refusal',5);}
 if(soil.pressure<.22&&soil.refusing){soil.refusing=false;queueSoil(soil,'release',4);}
 const permission=soil.refusing?.14:1;
 for(let g=0;g<3;g++){
  soil.voiceCharge[g]+=dt*energies[g];
  if(soil.voiceCharge[g]>3.2){soil.voiceCharge[g]=0;queueSoil(soil,['huldra','ledang','melusine'][g],1);}
  soil.food[g]+=dt*(energies[g]*.7+level*.16)*permission;
  if(soil.food[g]>.42&&soil.packets.length<24){
   soil.food[g]=0;const n=soil.nodes[soil.groups[g][0]],edge=n.edges[soil.serial++%n.edges.length];
   soil.packets.push({edge,from:n.id,u:0,source:g,strength:energies[g],hops:0,last:-1});
  }
 }
 for(const edge of soil.edges){
  const n=soil.nodes[edge.from],m=soil.nodes[edge.to];
  const local=Math.exp(-Math.pow((x-(n.x+m.x)*.5)*3,2));
  const feed=level*.4+(energies[n.group]+energies[m.group])*.3;
  if(edge.bridge<0){edge.conductance=permission;edge.growth=clamp(edge.growth+dt*feed*.22);}
  else{
   const target=edge.blocked?0:clamp(Math.max(level*spatial*local*3,(world.garden?.nearby||0)*.8))*permission;
   edge.conductance=lerp(edge.conductance,target,1-Math.exp(-dt*(target>edge.conductance?4:.55)));
   edge.growth=clamp(edge.growth+dt*edge.conductance*.35);
  }
  edge.light*=Math.exp(-dt*2.7);edge.memory*=Math.exp(-dt*.004);
 }
 for(const n of soil.nodes){n.light*=Math.exp(-dt*3);n.memory*=Math.exp(-dt*.004);}
 // Path following, arrival and route choice are real graph operations. No
 // all-pairs distance work, path search or topology rebuilding happens per tick.
 for(let i=soil.packets.length-1;i>=0;i--){
  const p=soil.packets[i],edge=soil.edges[p.edge];
  if(edge.blocked||edge.conductance<.025){soil.packets.splice(i,1);continue;}
  p.u=Math.min(edge.growth,p.u+dt*(.065+level*.07)*Math.max(.25,edge.conductance)/Math.max(.02,edge.length));
  edge.light=Math.max(edge.light,.35+p.strength*.5);edge.memory=Math.max(edge.memory,.25);
  if(p.u<1)continue;
  const to=edge.from===p.from?edge.to:edge.from,node=soil.nodes[to];node.light=.8;node.memory=.5;soil.arrivals++;
  if(edge.bridge>=0){soil.contacts[edge.bridge]++;queueSoil(soil,edge.key,3);}
  if(++p.hops>20){soil.packets.splice(i,1);continue;}
  const options=node.edges.filter(id=>id!==p.edge&&!soil.edges[id].blocked&&soil.edges[id].conductance>.12&&soil.edges[id].growth>.98);
  if(!options.length){soil.packets.splice(i,1);continue;}
  options.sort((u,v)=>{const a=soil.edges[u],b=soil.edges[v];return (b.bridge>=0?1:0)-(a.bridge>=0?1:0);});
  const routed=options[0];p.from=to;p.edge=soil.edges[routed].bridge>=0?routed:options[(soil.serial++ + p.hops)%options.length];p.u=0;
 }
 if(soil.arrivals-soil.storyArrivals>=18){soil.storyArrivals=soil.arrivals;queueSoil(soil,'roots',1);}
 if(soil===H.ecology)updateSoilStory(soil,dt);return soil;
}
function drawSoil(world,roots,threads,sediment){
 const soil=world.ecology,w=world.w,h=world.h,unit=Math.min(w,h*1.5);
 const palette=[[191,139,77],[93,157,163],[168,183,189]],moss=[109,131,96];
 // Thicker tapering roots join the feet to three local fungal patches.
 for(let g=0;g<3;g++){
  const ent=world.entities[g],port=soil.nodes[soil.groups[g][0]],col=palette[g];
  const footY=Math.min(h*.78,ent.y+ent.R*(g===2?2.3:2.1));
  for(let j=0;j<6;j++){
   const spread=(j/5-.5)*unit*.09,px=port.x*w+spread,py=port.y*h+(j%3)*h*.024;
   roots.beginPath();roots.moveTo(ent.x+(j-2.5)*ent.R*.055,footY);
   roots.bezierCurveTo(ent.x+spread*.3,lerp(footY,py,.3),px-spread*.25,lerp(footY,py,.8),px,py);
   roots.strokeStyle=v18Color(col,.10+soil.activity*.17+port.light*.18);roots.lineWidth=(1.6-j*.18)*(unit/960);roots.lineCap='round';roots.stroke();
  }
 }
 for(const e of soil.edges){
  const a=soil.nodes[e.from],b=soil.nodes[e.to],bridge=e.bridge>=0;
  const ctx=bridge?threads:roots,col=bridge?palette[soil.nodes[e.from].group]:moss;
  const alpha=e.blocked?.08:(bridge?.035+e.conductance*.24:.03+e.growth*.24)+e.light*.32+e.memory*.08;
  const progress=e.blocked?1:Math.max(.025,e.growth),points=[];
  for(let i=0;i<=12;i++)points.push(soilEdgePoint(soil,e,i/12*progress,w,h));
  if(e.blocked){ctx.setLineDash([2,9]);}
  v18Path(ctx,points,col,alpha,bridge?1.0:.65+e.light*.6);if(e.blocked)ctx.setLineDash([]);
  if(e.light>.025){const center=soilEdgePoint(soil,e,.5,w,h);v18Glow(ctx,center[0],center[1],unit*.008,col,e.light*.08);}
 }
 for(const e of soil.bridges)if(!e.blocked&&e.growth>.98&&e.conductance>.07){
  const a=world.entities[soil.nodes[e.from].group],b=world.entities[soil.nodes[e.to].group],points=[];
  for(let i=0;i<=24;i++){const u=i/24;points.push([lerp(a.x,b.x,u),lerp(a.y,b.y,u)+Math.sin(u*Math.PI)*h*.12]);}
  v18Path(threads,points,[181,190,161],e.conductance*.17,.75);
 }
 for(const p of soil.packets){
  const e=soil.edges[p.edge];if(p.u>e.growth)continue;
  const u=e.from===p.from?p.u:1-p.u,point=soilEdgePoint(soil,e,u,w,h),col=palette[p.source];
  v18Glow(e.bridge>=0?threads:roots,point[0],point[1],unit*.0055,col,.5+p.strength*.35);
 }
 for(const n of soil.nodes)if(n.light>.07)v18Glow(roots,n.x*w,n.y*h,unit*.006,palette[n.group],n.light*.42);
 // Retained words have real predecessors; only three fragments remain at once.
 if(H.textSettings.visible){
  sediment.font=`${Math.max(11,Math.min(15,unit*.015))}px Georgia,serif`;sediment.textAlign='center';
  for(const s of soil.story.shown){
   if(!soilLineAllowed(s.line))continue;
   const voice=soilVoice(s.line),urdu=voice?.lang==='ur'&&!H.textSettings.romanUrdu;
   const fragment=voice?.localized?s.line[H.textSettings.lang==='en'?3:2]:voice?(voice.lang==='ur'&&H.textSettings.romanUrdu?voice.romanFragment:voice.fragment):s.line[H.textSettings.lang==='en'?3:2];
   sediment.font=`${Math.max(urdu?14:11,Math.min(urdu?18:15,unit*.015))}px ${urdu?SOIL_URDU:SOIL_SERIF}`;sediment.direction=urdu?'rtl':'ltr';
   sediment.fillStyle=v18Color([172,181,163],.15*Math.exp(-s.age/65));sediment.fillText(fragment,s.x*w,s.y*h,w*.25);
  }
  sediment.direction='ltr';
 }
}
function uiText(norwegian,english){return H.textSettings?.lang==='no'?norwegian:english;}
function installTextControls(){
 const panel=H.audioControls;if(!panel)return;
 const inner=panel.querySelector('.audio-panel');if(!inner)return;
 const summary=panel.querySelector('summary');
 document.getElementById('hagen-language-controls')?.remove();
 const languages=document.createElement('div');languages.id='hagen-language-controls';languages.className='audio-row';
 languages.dataset.hagenAudio='true';languages.setAttribute('role','group');
 const style=document.createElement('style');style.textContent=`
  #hagen-language-controls button{min-width:48px;min-height:44px;letter-spacing:.08em;touch-action:manipulation}
  #hagen-language-controls button[aria-pressed="true"]{color:#f0e3c5;border-bottom:2px solid #ccb98d;background:rgba(204,185,141,.08)}
 `;languages.appendChild(style);
 const languageButtons=[];
 const toggle=document.createElement('button');toggle.type='button';toggle.id='hagen-text-toggle';
 const help=document.createElement('p');
 const translations=document.createElement('button');translations.type='button';translations.id='hagen-translations';
 const culture=document.createElement('button');culture.type='button';culture.id='hagen-culture';
 culture.setAttribute('aria-controls','hagen-soil-voices');culture.setAttribute('aria-describedby','hagen-culture-help');
 const cultureHelp=document.createElement('p');cultureHelp.id='hagen-culture-help';
 const urduLabel=document.createElement('label');urduLabel.htmlFor='hagen-urdu-script';
 const urdu=document.createElement('select');urdu.id='hagen-urdu-script';
 for(const [value,label]of [['script','اردو'],['roman','Roman Urdu']]){const option=document.createElement('option');option.value=value;option.textContent=label;option.lang=value==='script'?'ur':'en';option.dir=value==='script'?'rtl':'ltr';urdu.appendChild(option);}
 const updateLabels=()=>{
  panel.lang=H.textSettings.lang==='en'?'en':'nb';
  summary.textContent=uiText('Tilgjengelighet','Accessibility');
  languages.setAttribute('aria-label',uiText('Språk','Language'));
  toggle.textContent=H.textSettings.visible?uiText('Tekst på','Text on'):uiText('Tekst av','Text off');
  toggle.setAttribute('aria-pressed',String(H.textSettings.visible));
  help.textContent=uiText('Gå forbi røttene for å sette forbindelsene i bevegelse. Knappene nedenfor lukker eller åpner en rute.','Walk past roots to set their connections in motion. Use the route buttons below to close or reopen a path.');
  culture.textContent=H.textSettings.culture?uiText('Kultur på','Culture on'):uiText('Kultur av','Culture off');
  culture.setAttribute('aria-pressed',String(H.textSettings.culture));
  cultureHelp.textContent=uiText('Viser tekst på originalspråk, blant annet malayisk, fransk og urdu, med valgfrie oversettelser. Hovedfortellingen styres av Tekst.','Shows original-language text, including Malay, French and Urdu, with optional translations. Text controls the main narration.');
  translations.disabled=urdu.disabled=!H.textSettings.culture;
  translations.textContent=H.textSettings.translations?uiText('Oversettelser på','Translations on'):uiText('Oversettelser av','Translations off');
  translations.setAttribute('aria-pressed',String(H.textSettings.translations));
  urduLabel.textContent=uiText('Urdu-skrift','Urdu script');urdu.value=H.textSettings.romanUrdu?'roman':'script';
  clearSoilSediment();H.updateAudioLanguage?.();renderSoilText();H.refreshInstallation?.();
 };
 const setLanguage=value=>{
  const lang=value==='no'?'no':'en';H.textSettings.lang=lang;
  for(const entry of languageButtons)entry.button.setAttribute('aria-pressed',String(entry.value===lang));
  updateLabels();
 };
 for(const [value,label,name]of [['no','NOR','Norsk'],['en','ENG','English']]){
  const button=document.createElement('button');button.type='button';button.textContent=label;
  button.lang=value==='en'?'en':'nb';button.setAttribute('aria-label',name);button.title=name;
  button.addEventListener('click',()=>setLanguage(value));languages.appendChild(button);languageButtons.push({value,button});
 }
 inner.appendChild(languages);
 const textRow=document.createElement('div');textRow.className='audio-row';textRow.appendChild(toggle);textRow.appendChild(culture);inner.appendChild(textRow);
 inner.appendChild(cultureHelp);inner.appendChild(translations);
 inner.appendChild(urduLabel);inner.appendChild(urdu);inner.appendChild(help);
 H.languageControls=languages;H.setTextLanguage=setLanguage;H.setCultureEnabled=setCultureEnabled;H.refreshTextControls=updateLabels;
 culture.addEventListener('click',()=>setCultureEnabled(!H.textSettings.culture));
 toggle.addEventListener('click',()=>{H.textSettings.visible=!H.textSettings.visible;updateLabels();});
 translations.addEventListener('click',()=>{H.textSettings.translations=!H.textSettings.translations;updateLabels();});
 urdu.addEventListener('change',()=>{H.textSettings.romanUrdu=urdu.value==='roman';updateLabels();});
 setLanguage(H.textSettings.lang);
}

function exportSignals(dt,a=A,c=H.camera){
 const gv=H.runtime.globalVars||{};
 const audioDrive=clamp(a.rmsN*.62+a.spread*.25+a.kick*.28+a.onset*.18);
 const roomDrive=clamp(c.occupancy*.5+c.motion*.28+c.spread*.22),hybridDrive=audioDrive*roomDrive;
 const energy=clamp(audioDrive*.78+roomDrive*.18+hybridDrive*.42,0,1.4);
 NAR.eFast=lerp(NAR.eFast,energy,1-Math.exp(-dt*8));NAR.eSlow=lerp(NAR.eSlow,energy,1-Math.exp(-dt*.72));
 NAR.intensity=NAR.eFast;NAR.build=clamp((NAR.eFast-NAR.eSlow)*3.4);NAR.drop=clamp((NAR.eSlow-NAR.eFast)*3.4);
 const now=performance.now();
 if(audioDrive<.06&&roomDrive<.06){NAR.quietSince=NAR.quietSince||now;if(now-NAR.quietSince>6000)NAR.charge=Math.max(0,NAR.charge-dt*220);}
 else{NAR.quietSince=0;NAR.charge+=dt*1000*clamp(.14+energy*1.75+NAR.build*.95+a.beat*.22+hybridDrive*.7,.08,3.3);}
 const e=H.livingWorld?.entities||[];
 const map={Bass01:a.bassN,Low01:a.low,Mid01:a.mid,High01:a.high,OnLow:a.onLow,OnMid:a.onMid,OnHigh:a.onHigh,
 Centroid:a.centroid,Spread:a.spread,Kick01:a.kick,Beat01:a.beat,Level01:a.rmsN,Peak01:a.peakN,MicLevel:a.rmsN,
 MicPeak:a.peakN,MicFloor:a.floor,MicLive:A.ready?1:0,DemoMode:H.session.mode==='demo'?1:0,VoiceHz:H.voice.hz,VoiceConfidence:H.voice.conf,Iron01:H.voice.iron,Tin01:H.voice.tin,Silver01:H.voice.silver,HagenAct:H.drama.index,CameraReady:c.active?1:0,Motion01:c.motion,MotionLeft:c.left,
 MotionCenter:c.center,MotionRight:c.right,Occupancy01:c.occupancy,Stillness01:c.stillness,RoomX:c.x,RoomY:c.y,
 RoomSpread:c.spread,NarrativeCharge:NAR.charge,HuldraEnergy:e[0]?.e||0,LedangEnergy:e[1]?.e||0,MelusineEnergy:e[2]?.e||0,
 RelationHL:H.ecology?.bridges[0].conductance||0,RelationHM:H.ecology?.bridges[1].conductance||0,RelationLM:H.ecology?.bridges[2].conductance||0,AudioDrive:audioDrive,RoomDrive:roomDrive,HybridDrive:hybridDrive};
 for(const [key,value]of Object.entries(map))if(Object.prototype.hasOwnProperty.call(gv,key))gv[key]=value;
}
